CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY AUTOINCREMENT,username TEXT UNIQUE NOT NULL,hash TEXT NOT NULL,salt TEXT NOT NULL,must_change INTEGER DEFAULT 1,hint_first TEXT DEFAULT '',hint_last TEXT DEFAULT '');
CREATE TABLE IF NOT EXISTS sessions(token TEXT PRIMARY KEY,user_id INTEGER NOT NULL,expires INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS tasks(id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER NOT NULL,date TEXT NOT NULL,title TEXT NOT NULL,done INTEGER DEFAULT 0,priority INTEGER DEFAULT 1,time TEXT DEFAULT '',category TEXT DEFAULT '');
CREATE INDEX IF NOT EXISTS i_tasks ON tasks(user_id,date);
CREATE TABLE IF NOT EXISTS days(user_id INTEGER NOT NULL,date TEXT NOT NULL,p1 TEXT DEFAULT '',p2 TEXT DEFAULT '',p3 TEXT DEFAULT '',notes TEXT DEFAULT '',mood INTEGER DEFAULT 0,water INTEGER DEFAULT 0,PRIMARY KEY(user_id,date));
CREATE TABLE IF NOT EXISTS periods(id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER NOT NULL,start_date TEXT NOT NULL,end_date TEXT DEFAULT '');
CREATE INDEX IF NOT EXISTS i_periods ON periods(user_id,start_date);
